import { Separator as SeparatorPrimitive } from "@ui-sdk/react/separator"
import type { ComponentProps } from "react"
import { withClass } from "@/lib/utils"
import { separatorStyles } from "./separator.styles"

function Separator({ className, ...props }: ComponentProps<typeof SeparatorPrimitive>) {
  return (
    <SeparatorPrimitive
      className={withClass(
        separatorStyles.root,
        className,
      )}
      {...props}
    />
  )
}

export { Separator }

// Framework-free: plain class strings for each part, so any version of 13UI can share them.
export const separatorStyles = {
  root: "shrink-0 bg-border data-[orientation=horizontal]:h-px data-[orientation=horizontal]:w-full data-[orientation=vertical]:h-4 data-[orientation=vertical]:w-px",
}
